## Design Note

Tokenizer: lazy single-pass scanner producing typed tokens with source positions. Parser: iterative state-machine with explicit stack (no recursion), emitting a flat instruction stream (stack-machine bytecode). `if` compiles to JIF/JMP for lazy branching. Evaluator: iterative bytecode interpreter with local stack — no recursion, no shared mutable state → thread-safe. Complexity: O(n) compile, O(n) evaluate per call, O(n) memory. Concurrency: `Expr` is immutable post-construction; `evaluate` uses only local variables.

### solution.py
```python
"""Safe formula engine for spreadsheet cells.

Implements a sandboxed expression language: compile once to a flat
instruction stream, evaluate many times via an iterative stack machine.
No eval/exec/compile/ast; no recursion in parser or evaluator.
"""

import math
from typing import Mapping

__all__ = [
    "ExprError", "ExprSyntaxError", "ExprNameError", "ExprEvalError",
    "Expr", "compile_expr", "evaluate",
]

# ─── Exceptions ───────────────────────────────────────────────────────────────

class ExprError(Exception):
    """Base of every error below."""

class ExprSyntaxError(ExprError):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.message = message
        self.position = position

class ExprNameError(ExprError):
    def __init__(self, name: str):
        super().__init__(f"unknown function '{name}'")
        self.name = name

class ExprEvalError(ExprError):
    pass

# ─── Token types ──────────────────────────────────────────────────────────────

_T_NUM   = 0
_T_IDENT = 1
_T_OP    = 2   # + - * / % ^
_T_CMP   = 3   # < <= > >= == !=
_T_LPAREN = 4
_T_RPAREN = 5
_T_COMMA  = 6

# ─── Instruction tags ─────────────────────────────────────────────────────────

_I_CONST  = 0
_I_VAR    = 1
_I_ADD    = 2
_I_SUB    = 3
_I_MUL    = 4
_I_DIV    = 5
_I_MOD    = 6
_I_POW    = 7
_I_NEG    = 8
_I_CMP_LT = 10
_I_CMP_LE = 11
_I_CMP_GT = 12
_I_CMP_GE = 13
_I_CMP_EQ = 14
_I_CMP_NE = 15
_I_FUNC   = 16
_I_JIF    = 17
_I_JMP    = 18

_BIN_TAG = {
    '+': _I_ADD, '-': _I_SUB, '*': _I_MUL, '/': _I_DIV, '%': _I_MOD,
}
_CMP_TAG = {
    '<': _I_CMP_LT, '<=': _I_CMP_LE, '>': _I_CMP_GT,
    '>=': _I_CMP_GE, '==': _I_CMP_EQ, '!=': _I_CMP_NE,
}

# Valid functions: name -> (min_args, max_args_or_None)
_FUNC_SIG = {
    'abs':   (1, 1),
    'sqrt':  (1, 1),
    'min':   (1, None),
    'max':   (1, None),
    'round': (1, 2),
    'if':    (3, 3),
}

# ─── Tokenizer + Parser (combined class for lazy tokenization) ────────────────

class _Parser:
    __slots__ = ('src', 'pos', 'ct', 'cv', 'cp')

    def __init__(self, src: str):
        self.src = src
        self.pos = 0   # scan position in src
        self.ct = None  # current token type
        self.cv = None  # current token value
        self.cp = 0     # current token source position
        self._advance()

    # ── tokenizer ──

    def _advance(self):
        src = self.src
        n = len(src)
        pos = self.pos
        # skip whitespace
        while pos < n and src[pos] in ' \t\n\r':
            pos += 1
        if pos >= n:
            self.ct = None
            self.cp = n
            self.pos = pos
            return
        ch = src[pos]
        # number starting with digit
        if '0' <= ch <= '9':
            self._read_number(pos)
            return
        # number starting with '.'
        if ch == '.':
            if pos + 1 < n and '0' <= src[pos + 1] <= '9':
                self._read_number(pos)
            else:
                raise ExprSyntaxError("invalid character '.'", pos)
            return
        # identifier
        if ('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ch == '_':
            start = pos
            pos += 1
            while pos < n:
                c = src[pos]
                if ('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9') or c == '_':
                    pos += 1
                else:
                    break
            self.ct = _T_IDENT
            self.cv = src[start:pos]
            self.cp = start
            self.pos = pos
            return
        # operators / punctuation
        self.cp = pos
        if ch == '+': self.ct, self.cv, self.pos = _T_OP, '+', pos + 1
        elif ch == '-': self.ct, self.cv, self.pos = _T_OP, '-', pos + 1
        elif ch == '*': self.ct, self.cv, self.pos = _T_OP, '*', pos + 1
        elif ch == '/': self.ct, self.cv, self.pos = _T_OP, '/', pos + 1
        elif ch == '%': self.ct, self.cv, self.pos = _T_OP, '%', pos + 1
        elif ch == '^': self.ct, self.cv, self.pos = _T_OP, '^', pos + 1
        elif ch == '(': self.ct, self.cv, self.pos = _T_LPAREN, '(', pos + 1
        elif ch == ')': self.ct, self.cv, self.pos = _T_RPAREN, ')', pos + 1
        elif ch == ',': self.ct, self.cv, self.pos = _T_COMMA, ',', pos + 1
        elif ch == '<':
            if pos + 1 < n and src[pos + 1] == '=':
                self.ct, self.cv, self.pos = _T_CMP, '<=', pos + 2
            else:
                self.ct, self.cv, self.pos = _T_CMP, '<', pos + 1
        elif ch == '>':
            if pos + 1 < n and src[pos + 1] == '=':
                self.ct, self.cv, self.pos = _T_CMP, '>=', pos + 2
            else:
                self.ct, self.cv, self.pos = _T_CMP, '>', pos + 1
        elif ch == '=':
            if pos + 1 < n and src[pos + 1] == '=':
                self.ct, self.cv, self.pos = _T_CMP, '==', pos + 2
            else:
                raise ExprSyntaxError("invalid character '='", pos)
        elif ch == '!':
            if pos + 1 < n and src[pos + 1] == '=':
                self.ct, self.cv, self.pos = _T_CMP, '!=', pos + 2
            else:
                raise ExprSyntaxError("invalid character '!'", pos)
        else:
            raise ExprSyntaxError(f"invalid character '{ch}'", pos)

    def _read_number(self, start):
        src = self.src
        n = len(src)
        pos = start
        # integer part
        while pos < n and '0' <= src[pos] <= '9':
            pos += 1
        # fractional part
        if pos < n and src[pos] == '.':
            pos += 1
            while pos < n and '0' <= src[pos] <= '9':
                pos += 1
        # exponent
        if pos < n and src[pos] in 'eE':
            pos += 1
            if pos < n and src[pos] in '+-':
                pos += 1
            if pos >= n or not ('0' <= src[pos] <= '9'):
                raise ExprSyntaxError("malformed number", start)
            while pos < n and '0' <= src[pos] <= '9':
                pos += 1
        text = src[start:pos]
        val = float(text)
        if not math.isfinite(val):
            raise ExprSyntaxError("number overflow", start)
        self.ct = _T_NUM
        self.cv = val
        self.cp = start
        self.pos = pos

    # ── parser helpers ──

    def _consume(self):
        """Return current token info and advance."""
        info = (self.ct, self.cv, self.cp)
        self._advance()
        return info

    def _err_pos(self):
        return self.cp if self.ct is not None else len(self.src)

    # ── main iterative parse ──

    def parse(self):
        insns: list = []
        stack: list = [('want_expr',)]

        while stack:
            f = stack[-1]
            kind = f[0]

            if kind == 'want_expr':
                stack[-1] = ('after_sum',)
                stack.append(('want_sum',))

            elif kind == 'after_sum':
                stack.pop()
                if self.ct == _T_CMP:
                    op = self.cv
                    self._consume()
                    stack.append(('do_cmp', op))
                    stack.append(('want_sum',))

            elif kind == 'do_cmp':
                _, op = stack.pop()
                insns.append((_CMP_TAG[op],))

            elif kind == 'want_sum':
                stack[-1] = ('sum_loop',)
                stack.append(('want_term',))

            elif kind == 'sum_loop':
                if self.ct == _T_OP and self.cv in ('+', '-'):
                    op = self.cv
                    self._consume()
                    stack[-1] = ('sum_do', op)
                    stack.append(('want_term',))
                else:
                    stack.pop()

            elif kind == 'sum_do':
                _, op = stack.pop()
                insns.append((_BIN_TAG[op],))
                stack.append(('sum_loop',))

            elif kind == 'want_term':
                stack[-1] = ('term_loop',)
                stack.append(('want_unary',))

            elif kind == 'term_loop':
                if self.ct == _T_OP and self.cv in ('*', '/', '%'):
                    op = self.cv
                    self._consume()
                    stack[-1] = ('term_do', op)
                    stack.append(('want_unary',))
                else:
                    stack.pop()

            elif kind == 'term_do':
                _, op = stack.pop()
                insns.append((_BIN_TAG[op],))
                stack.append(('term_loop',))

            elif kind == 'want_unary':
                if self.ct == _T_OP and self.cv in ('+', '-'):
                    op = self.cv
                    self._consume()
                    stack[-1] = ('unary_do', op)
                    stack.append(('want_unary',))
                else:
                    stack[-1] = ('want_power',)

            elif kind == 'unary_do':
                _, op = stack.pop()
                if op == '-':
                    insns.append((_I_NEG,))
                # '+' is a no-op

            elif kind == 'want_power':
                stack[-1] = ('power_check',)
                stack.append(('want_primary',))

            elif kind == 'power_check':
                stack.pop()
                if self.ct == _T_OP and self.cv == '^':
                    self._consume()
                    stack.append(('power_do',))
                    stack.append(('want_unary',))

            elif kind == 'power_do':
                stack.pop()
                insns.append((_I_POW,))

            elif kind == 'want_primary':
                self._parse_primary(insns, stack)

            elif kind == 'paren_done':
                stack.pop()
                if self.ct == _T_RPAREN:
                    self._consume()
                else:
                    raise ExprSyntaxError("expected ')'", self._err_pos())

            elif kind == 'func_arg_done':
                _, name, name_pos, nargs = stack.pop()
                if self.ct == _T_COMMA:
                    self._consume()
                    stack.append(('func_arg_done', name, name_pos, nargs + 1))
                    stack.append(('want_expr',))
                elif self.ct == _T_RPAREN:
                    self._consume()
                    insns.append((_I_FUNC, name, nargs, name_pos))
                else:
                    raise ExprSyntaxError("expected ',' or ')'", self._err_pos())

            elif kind == 'if_cond_done':
                _, name, name_pos = stack.pop()
                jif_idx = len(insns)
                insns.append((_I_JIF, -1))
                stack.append(('if_then_done', name, name_pos, jif_idx))
                stack.append(('want_expr',))

            elif kind == 'if_then_done':
                _, name, name_pos, jif_idx = stack.pop()
                jmp_idx = len(insns)
                insns.append((_I_JMP, -1))
                insns[jif_idx] = (_I_JIF, len(insns))
                if self.ct == _T_COMMA:
                    self._consume()
                else:
                    raise ExprSyntaxError("expected ','", self._err_pos())
                stack.append(('if_else_done', name, name_pos, jmp_idx))
                stack.append(('want_expr',))

            elif kind == 'if_else_done':
                _, name, name_pos, jmp_idx = stack.pop()
                insns[jmp_idx] = (_I_JMP, len(insns))
                if self.ct == _T_RPAREN:
                    self._consume()
                else:
                    raise ExprSyntaxError("expected ')'", self._err_pos())

        # trailing tokens?
        if self.ct is not None:
            raise ExprSyntaxError("unexpected token", self.cp)

        return insns

    def _parse_primary(self, insns, stack):
        if self.ct is None:
            raise ExprSyntaxError("unexpected end of input", len(self.src))
        if self.ct == _T_NUM:
            val = self.cv
            self._consume()
            insns.append((_I_CONST, val))
            stack.pop()
        elif self.ct == _T_IDENT:
            name = self.cv
            name_pos = self.cp
            self._consume()
            if self.ct == _T_LPAREN:
                self._consume()  # '('
                if self.ct == _T_RPAREN:
                    self._consume()  # ')' empty arg list
                    insns.append((_I_FUNC, name, 0, name_pos))
                    stack.pop()
                elif name == 'if':
                    stack[-1] = ('if_cond_done', name, name_pos)
                    stack.append(('want_expr',))
                else:
                    stack[-1] = ('func_arg_done', name, name_pos, 1)
                    stack.append(('want_expr',))
            else:
                insns.append((_I_VAR, name))
                stack.pop()
        elif self.ct == _T_LPAREN:
            self._consume()  # '('
            stack[-1] = ('paren_done',)
            stack.append(('want_expr',))
        else:
            raise ExprSyntaxError("unexpected token", self.cp)

# ─── Post-parse validation ────────────────────────────────────────────────────

def _validate(insns):
    """Check function names and argument counts. Leftmost error wins."""
    best_pos = None
    best_err = None
    for ins in insns:
        if ins[0] == _I_FUNC:
            name, nargs, name_pos = ins[1], ins[2], ins[3]
            sig = _FUNC_SIG.get(name)
            if sig is None:
                if best_pos is None or name_pos < best_pos:
                    best_pos = name_pos
                    best_err = ExprNameError(name)
            else:
                lo, hi = sig
                if nargs < lo or (hi is not None and nargs > hi):
                    if best_pos is None or name_pos < best_pos:
                        best_pos = name_pos
                        best_err = ExprSyntaxError(
                            f"wrong number of arguments for '{name}'", name_pos)
    if best_err is not None:
        raise best_err

# ─── Evaluator (iterative stack machine) ──────────────────────────────────────

def _eval(insns, variables):
    st: list = []
    push = st.append
    pop = st.pop
    pc = 0
    n = len(insns)
    isfinite = math.isfinite

    while pc < n:
        ins = insns[pc]
        t = ins[0]

        if t == _I_CONST:
            push(ins[1])
        elif t == _I_VAR:
            name = ins[1]
            try:
                v = float(variables[name])
            except KeyError:
                raise ExprNameError(name)
            except (TypeError, ValueError):
                raise ExprEvalError(f"non-numeric value for '{name}'")
            if not isfinite(v):
                raise ExprEvalError(f"non-finite value for '{name}'")
            push(v)
        elif t == _I_ADD:
            r = pop(); v = pop() + r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_SUB:
            r = pop(); v = pop() - r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_MUL:
            r = pop(); v = pop() * r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_DIV:
            r = pop()
            if r == 0.0:
                raise ExprEvalError("division by zero")
            v = pop() / r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_MOD:
            r = pop()
            if r == 0.0:
                raise ExprEvalError("modulo by zero")
            v = pop() % r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_POW:
            r = pop(); l = pop()
            if l == 0.0 and r < 0.0:
                raise ExprEvalError("zero to negative power")
            if l < 0.0 and r != int(r):
                raise ExprEvalError("negative base to non-integer power")
            v = l ** r
            if not isfinite(v): raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_NEG:
            push(-pop())
        elif t == _I_CMP_LT:
            r = pop(); push(1.0 if pop() < r else 0.0)
        elif t == _I_CMP_LE:
            r = pop(); push(1.0 if pop() <= r else 0.0)
        elif t == _I_CMP_GT:
            r = pop(); push(1.0 if pop() > r else 0.0)
        elif t == _I_CMP_GE:
            r = pop(); push(1.0 if pop() >= r else 0.0)
        elif t == _I_CMP_EQ:
            r = pop(); push(1.0 if pop() == r else 0.0)
        elif t == _I_CMP_NE:
            r = pop(); push(1.0 if pop() != r else 0.0)
        elif t == _I_FUNC:
            name = ins[1]
            nargs = ins[2]
            if nargs == 1:
                a0 = pop()
                if name == 'abs':
                    v = abs(a0)
                elif name == 'sqrt':
                    if a0 < 0.0:
                        raise ExprEvalError("sqrt of negative number")
                    v = math.sqrt(a0)
                elif name == 'min':
                    v = a0
                elif name == 'max':
                    v = a0
                elif name == 'round':
                    v = float(round(a0))
                else:
                    raise ExprEvalError(f"unknown function '{name}'")
            elif nargs == 2:
                a1 = pop(); a0 = pop()
                if name == 'round':
                    nd = a1
                    if nd != int(nd):
                        raise ExprEvalError("round digit count not integer")
                    v = float(round(a0, int(nd)))
                elif name == 'min':
                    v = a0 if a0 <= a1 else a1
                elif name == 'max':
                    v = a0 if a0 >= a1 else a1
                else:
                    raise ExprEvalError(f"unknown function '{name}'")
            else:
                # min/max with 3+ args, or round with 1 arg (handled above)
                args = [pop() for _ in range(nargs)]
                args.reverse()
                if name == 'min':
                    v = min(args)
                elif name == 'max':
                    v = max(args)
                else:
                    raise ExprEvalError(f"unknown function '{name}'")
            if not isfinite(v):
                raise ExprEvalError("result not finite")
            push(v)
        elif t == _I_JIF:
            if pop() == 0.0:
                pc = ins[1]
                continue
        elif t == _I_JMP:
            pc = ins[1]
            continue

        pc += 1

    return st[0]

# ─── Public API ───────────────────────────────────────────────────────────────

class Expr:
    """Compiled, immutable expression."""
    __slots__ = ('source', 'variables', '_insns')

    def __init__(self, source: str, variables: frozenset, insns: tuple):
        self.source = source
        self.variables = variables
        self._insns = insns

    def evaluate(self, variables: Mapping[str, float] | None = None) -> float:
        if variables is None:
            variables = {}
        return _eval(self._insns, variables)


def compile_expr(src: str) -> Expr:
    if not isinstance(src, str):
        raise TypeError(f"expected str, got {type(src).__name__}")
    parser = _Parser(src)
    insns = parser.parse()
    _validate(insns)
    var_names = frozenset(
        ins[1] for ins in insns if ins[0] == _I_VAR
    )
    return Expr(src, var_names, tuple(insns))


def evaluate(src: str, variables: Mapping[str, float] | None = None) -> float:
    return compile_expr(src).evaluate(variables)
```

### test_solution.py
```python
"""Pytest suite for the safe formula engine."""

import math
import threading
import pytest
import solution
from solution import (
    ExprError, ExprSyntaxError, ExprNameError, ExprEvalError,
    Expr, compile_expr, evaluate,
)


# ─── helpers ──────────────────────────────────────────────────────────────────

def ev(src, vars=None):
    return evaluate(src, vars)

def comp(src):
    return compile_expr(src)


# ─── basic numbers ────────────────────────────────────────────────────────────

class TestNumbers:
    def test_integer(self):
        assert ev("42") == 42.0

    def test_leading_zeros(self):
        assert ev("007") == 7.0

    def test_decimal(self):
        assert ev("3.25") == 3.25

    def test_trailing_dot(self):
        assert ev("5.") == 5.0

    def test_leading_dot(self):
        assert ev(".5") == 0.5

    def test_exp_positive(self):
        assert ev("1e3") == 1000.0

    def test_exp_negative(self):
        assert ev("1.5E-3") == 0.0015

    def test_exp_plus(self):
        assert ev(".5e+1") == 5.0

    def test_return_type_float(self):
        assert isinstance(ev("1"), float)

    def test_overflow_number_compile_error(self):
        with pytest.raises(ExprSyntaxError) as ei:
            comp("1e999")
        assert ei.value.position == 0


# ─── arithmetic ───────────────────────────────────────────────────────────────

class TestArithmetic:
    def test_add(self):
        assert ev("1+2") == 3.0

    def test_sub(self):
        assert ev("5-3") == 2.0

    def test_mul(self):
        assert ev("3*4") == 12.0

    def test_div(self):
        assert ev("10/4") == 2.5

    def test_mod(self):
        assert ev("7%3") == 1.0

    def test_mod_negative_dividend(self):
        assert ev("-7%3") == 2.0

    def test_mod_negative_divisor(self):
        assert ev("7%-3") == -2.0

    def test_left_assoc_add(self):
        assert ev("10-3-2") == 5.0

    def test_left_assoc_mul(self):
        assert ev("2*3/4") == 1.5

    def test_precedence_mul_over_add(self):
        assert ev("2+3*4") == 14.0

    def test_parens(self):
        assert ev("(2+3)*4") == 20.0


# ─── unary ────────────────────────────────────────────────────────────────────

class TestUnary:
    def test_neg(self):
        assert ev("-3") == -3.0

    def test_double_neg(self):
        assert ev("--3") == 3.0

    def test_mixed_unary(self):
        assert ev("-+-3") == 3.0

    def test_unary_after_mul(self):
        assert ev("2*-3") == -6.0

    def test_unary_after_sub(self):
        assert ev("2--3") == 5.0

    def test_unary_plus(self):
        assert ev("+5") == 5.0


# ─── power ────────────────────────────────────────────────────────────────────

class TestPower:
    def test_basic(self):
        assert ev("2^3") == 8.0

    def test_right_assoc(self):
        assert ev("2^3^2") == 512.0

    def test_unary_left(self):
        assert ev("-2^2") == -4.0

    def test_paren_neg_base(self):
        assert ev("(-2)^2") == 4.0

    def test_neg_exp(self):
        assert ev("2^-2") == 0.25

    def test_neg_exp_right_assoc(self):
        assert ev("2^-1^2") == 0.5

    def test_neg_base_neg_exp(self):
        assert ev("-2^-2") == -0.25

    def test_power_tighter_than_mul(self):
        assert ev("2*3^2") == 18.0


# ─── comparisons ──────────────────────────────────────────────────────────────

class TestComparisons:
    def test_lt(self):
        assert ev("1<2") == 1.0

    def test_ge(self):
        assert ev("3>=3") == 1.0

    def test_eq(self):
        assert ev("2==2") == 1.0

    def test_ne(self):
        assert ev("1!=2") == 1.0

    def test_false(self):
        assert ev("2<1") == 0.0

    def test_nonassoc_error(self):
        with pytest.raises(ExprSyntaxError) as ei:
            comp("1 < 2 < 3")
        assert ei.value.position == 6

    def test_nonassoc_eq_ne(self):
        with pytest.raises(ExprSyntaxError):
            comp("1 == 2 != 3")

    def test_paren_allow_chain(self):
        assert ev("(1<2)<1") == 1.0  # (1<2)=1.0, 1.0<1 → 0.0
        assert ev("(1<2)<2") == 1.0  # 1.0<2 → 1.0

    def test_cmp_in_parens(self):
        assert ev("(1<2)") == 1.0

